diff --git a/io/io.cpp b/io/io.cpp
index 85f414f..af342b5 100644
--- a/io/io.cpp
+++ b/io/io.cpp
@@ -669,6 +669,64 @@ des_ce array_ce[MAX_CE];
 natl next_ce;

 // ( SOLUZIONE 2025-09-10
+/// @brief Parte C++ della primitiva ceasyncread_n()
+extern "C" natl c_ceasyncread_n(natl id, char *buf, natl quanti)
+{
+	if (id >= next_ce) {
+		flog(LOG_WARN, "ceasyncread_n: ce non riconosciuto: %u", id);
+		abort_p();
+	}
+
+	if (quanti == 0) {
+		flog(LOG_WARN, "ceasyncread_n: quanti == 0");
+		abort_p();
+	}
+
+	if (!access(buf, quanti, true)) {
+		flog(LOG_WARN, "ceasyncread_n: problemi di accesso al buffer");
+		abort_p();
+	}
+
+	des_ce *ce = &array_ce[id];
+	sem_wait(ce->mutex);
+
+	// Cerca un descrittore libero
+	int trid = -1;
+	for (int i = 0; i < MAX_CE_ASYNC; i++) {
+		if (!ce->tr[i].buf) {
+			trid = i;
+			break;
+		}
+	}
+
+	if (trid == -1) {
+		// Tutti i descrittori sono occupati
+		sem_signal(ce->mutex);
+		return 0xFFFFFFFF;
+	}
+
+	des_ce_tr *t = &ce->tr[trid];
+	t->buf = buf;
+	t->quanti = quanti;
+	t->next = 0xFFFFFFFF;
+
+	// Accoda il trasferimento
+	if (ce->last != 0xFFFFFFFF) {
+		// C'è gia' almeno un trasferimento in coda
+		ce->tr[ce->last].next = trid;
+	}
+	ce->last = trid;
+
+	// Se non c'è un trasferimento attivo, avvialo
+	if (ce->cur == 0xFFFFFFFF) {
+		ce->cur = trid;
+		// Abilita le interruzioni (bit 1 del registro di controllo)
+		outputb(inputb(ce->iCTL) | 0x01, ce->iCTL);
+	}
+
+	sem_signal(ce->mutex);
+	return trid;
+}
 //   SOLUZIONE 2025-09-10 )

 extern "C" void c_cewait(natl id, natl trid)
@@ -705,6 +763,43 @@ extern "C" void c_cewait(natl id, natl trid)
 extern "C" void estern_ce(natq id)
 {
 // ( SOLUZIONE 2025-09-10
+	for(;;) {
+		des_ce *ce = &array_ce[id];
+
+		// Legge un byte dal registro RBR
+		char c = inputb(ce->iRBR);
+
+		sem_wait(ce->mutex);
+
+		if (ce->cur != 0xFFFFFFFF) {
+			des_ce_tr *t = &ce->tr[ce->cur];
+			*t->buf = c;
+			t->buf++;
+			t->quanti--;
+
+			if (t->quanti == 0) {
+				// Trasferimento completato
+				// Sveglia i processi in attesa su sync
+				for (natl i = 0; i < ce->waiting; i++) {
+					sem_signal(ce->sync);
+				}
+				ce->waiting = 0;
+
+				// Passa al prossimo trasferimento
+				natl next = t->next;
+				ce->cur = next;
+
+				if (next == 0xFFFFFFFF) {
+					// Nessun altro trasferimento, disabilita interruzioni
+					ce->last = 0xFFFFFFFF;
+					outputb(inputb(ce->iCTL) & ~0x01, ce->iCTL);
+				}
+			}
+		}
+
+		sem_signal(ce->mutex);
+		wfi();
+	}
 //   SOLUZIONE 2025-09-10 )
 }

